query GetSkills {
  skills {
    name
    description
    content
    rootPath
    fileCount
    isReadonly
    isDisabled
    __typename
  }
}

query GetSkillNameIssues {
  skillNameIssues {
    name
    usedPath
    ignoredPaths
    kind
    __typename
  }
}

query GetApplicationsCapability {
  applicationsCapability {
    ...ApplicationsCapabilityFields
    __typename
  }
}

fragment ApplicationsCapabilityFields on ApplicationsCapability {
  enabled
  scope
  settingKey
  source
  __typename
}

query GetProjectsCapability {
  projectsCapability {
    ...ProjectsCapabilityFields
    __typename
  }
}

fragment ProjectsCapabilityFields on ProjectsCapability {
  enabled
  settingKey
  source
  __typename
}

query GetAllWorkspaces {
  workspaces {
    __typename
    workspaceId
    name
    displayName
    config
    workspaceRootPath
    absolutePath
    kind
    isTemp
  }
}

query ListCollaborationRootHistory {
  listCollaborationRootHistory {
    __typename
    ... on AgentOrgRootHistoryObject {
      root_subject_kind
      root_run_id
      created_at
      archived_at
      is_active
      summary
      org
      __typename
    }
    ... on AgentTeamRootHistoryObject {
      root_subject_kind
      root_run_id
      __typename
    }
  }
}

query GetAgentOrgDefinitions {
  agentOrgDefinitions {
    id
    name
    description
    instructions
    category
    avatarUrl
    revision
    handoffs {
      from
      to
      rules
      __typename
    }
    members {
      memberName
      ref
      refType
      refScope
      __typename
    }
    defaultLaunchConfig {
      llmModelIdentifier
      runtimeKind
      llmConfig
      __typename
    }
    __typename
  }
}

query GetSkillSources {
  skillSources {
    ...SkillSourceFields
    __typename
  }
  skillSourceRegistryError
}

fragment SkillSourceFields on SkillSource {
  sourceId
  sourceKind
  path
  skillCount
  isDefault
  github {
    repositoryUrl
    defaultBranch
    installedRevision
    latestRevision
    latestCheckedAt
    status
    lastError
    __typename
  }
  __typename
}

query GetSkillNameIssues {
